#include "kernel.h"

#include <cuco/static_multiset.cuh>

#include <cuda/stream_ref>

#include <cstdint>
#include <limits>

void static_multiset_build_and_count_each(
    const std::int32_t* build_keys,
    std::size_t build_size,
    const std::int32_t* probe_keys,
    std::size_t probe_size,
    std::int64_t* match_counts,
    cudaStream_t stream) {
  using key_type = std::int32_t;
  constexpr auto empty_key_sentinel = std::numeric_limits<key_type>::min();

  auto stream_ref = cuda::stream_ref{stream};

  auto multiset = cuco::static_multiset<key_type>{
      build_size * 2,
      cuco::empty_key<key_type>{empty_key_sentinel},
      {},
      {},
      {},
      {},
      {},
      stream_ref};

  multiset.insert_async(build_keys, build_keys + build_size, stream_ref);
  multiset.count_each(
      probe_keys,
      probe_keys + probe_size,
      multiset.key_eq(),
      multiset.hash_function(),
      match_counts,
      stream_ref);
}

#pragma once

#include <cstddef>
#include <cstdint>
#include <cuda_runtime_api.h>

void static_multiset_build_and_count_each(
    const std::int32_t* build_keys,
    std::size_t build_size,
    const std::int32_t* probe_keys,
    std::size_t probe_size,
    std::int64_t* match_counts,
    cudaStream_t stream);

#include "kernel.h"

#include <ATen/cuda/CUDAContext.h>
#include <torch/extension.h>

#include <cstddef>
#include <cstdint>
#include <string>

namespace {

void check_i32_vector(const torch::Tensor& tensor, const char* name) {
  TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
  TORCH_CHECK(tensor.scalar_type() == torch::kInt32, name, " must have int32 dtype");
  TORCH_CHECK(tensor.dim() == 1, name, " must be one-dimensional");
  TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

}  // namespace

void run(
    const torch::Tensor& build_keys,
    const torch::Tensor& probe_keys,
    torch::Tensor match_counts) {
  check_i32_vector(build_keys, "build_keys");
  check_i32_vector(probe_keys, "probe_keys");
  TORCH_CHECK(build_keys.numel() > 0, "build_keys must not be empty");
  TORCH_CHECK(match_counts.is_cuda(), "match_counts must be a CUDA tensor");
  TORCH_CHECK(match_counts.scalar_type() == torch::kInt64, "match_counts must have int64 dtype");
  TORCH_CHECK(match_counts.dim() == 1, "match_counts must be one-dimensional");
  TORCH_CHECK(match_counts.numel() == probe_keys.numel(), "match_counts has the wrong length");
  TORCH_CHECK(match_counts.is_contiguous(), "match_counts must be contiguous");
  TORCH_CHECK(
      build_keys.get_device() == probe_keys.get_device() &&
          build_keys.get_device() == match_counts.get_device(),
      "all tensors must be on the same CUDA device");

  static_multiset_build_and_count_each(
      build_keys.data_ptr<std::int32_t>(),
      static_cast<std::size_t>(build_keys.numel()),
      probe_keys.data_ptr<std::int32_t>(),
      static_cast<std::size_t>(probe_keys.numel()),
      match_counts.data_ptr<std::int64_t>(),
      at::cuda::getCurrentCUDAStream(build_keys.get_device()));
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) {
  module.def("run", &run, "Build a cuco::static_multiset and count each probe key");
}
